// ─── Types ────────────────────────────────────────────────────────────────────

export interface ImportRow {
  /** Zero-based row index in the original file (excluding header). */
  rowIndex: number;
  /** Raw cell values keyed by column header. */
  raw: Record<string, string>;
  /** Mapped MedicalIncident fields (partial). */
  mapped: Partial<MedicalIncident>;
  /**
   * Fields that need user resolution because fuzzy-matching returned multiple
   * candidates. Key = field name, value = list of candidates.
   */
  unresolved: Record<string, SelectOption[]>;
  /** Fields where mapping failed entirely (could not parse). */
  warnings: string[];
  /** User must pick date(s) when file has no valid report/occurrence dates. */
  dateUnresolved?: DateUnresolvedKind;
  /** Which field was filled from the other date (for preview hint). */
  dateFallbackUsed?: ('createdAt' | 'occurredAt')[];
  /** Set when a row failed during import — shown in retry review step. */
  importError?: string;
}

export type DateUnresolvedKind = 'both' | 'createdAt' | 'occurredAt';

export type ImportTemplate = 'danhsach' | 'phantich' | 'danhgia' | 'unknown';

export type ImportTabId = 'danhsach' | 'phantich' | 'danhgia';

export type TemplateConfidence = 'high' | 'medium' | 'low' | 'unknown';

/** Result of validating which form tab a file belongs to. */
export interface TemplateValidationResult {
  template: ImportTemplate;
  tabId: ImportTabId | null;
  confidence: TemplateConfidence;
  /** 0–100 match score */
  score: number;
  /** Header signals that matched this template */
  matchedSignals: string[];
  /** Expected signals not found in the file */
  missingSignals: string[];
  warnings: string[];
}

