function headerMatches(normalizedHeaders: string[], patterns: string[]): boolean {
  return patterns.some((p) => {
    const np = normalizeHeader(p);
    return normalizedHeaders.some((h) => h === np || h.includes(np) || np.includes(h));
  });
}

function scoreTemplate(normalizedHeaders: string[], sig: TemplateSignature) {
  const matchedSignals: string[] = [];
  const missingSignals: string[] = [];
  let score = 0;
  let maxScore = 0;

  for (const group of sig.signals) {
    maxScore += group.weight;
    const hit = headerMatches(normalizedHeaders, group.headers);
    if (hit) {
      score += group.weight;
      matchedSignals.push(group.label);
    } else {
      missingSignals.push(group.label);
    }
  }

  const meetsRequired = sig.requiredAny.some((reqGroup) =>
    reqGroup.some((req) => normalizedHeaders.some((h) => h.includes(normalizeHeader(req)))),
  );

  if (!meetsRequired) {
    score = Math.min(score, 40);
  }

  return { score, maxScore, matchedSignals, missingSignals, meetsRequired };
}

/** Validate which import tab a file belongs to, with confidence score. */
export function validateImportTemplate(headers: string[]): TemplateValidationResult {
  const normalized = headers.map(normalizeHeader).filter(Boolean);
  if (normalized.length === 0) {
    return {
      template: 'unknown', tabId: null, confidence: 'unknown', score: 0,
      matchedSignals: [], missingSignals: [], warnings: ['File không có header cột nào.'],
    };
  }

  const ranked = TEMPLATE_SIGNATURES
    .map((sig) => ({ sig, ...scoreTemplate(normalized, sig) }))
    .sort((a, b) => b.score - a.score);

  const best = ranked[0];
  const second = ranked[1];
  const pct = best.maxScore > 0 ? Math.round((best.score / best.maxScore) * 100) : 0;

  let confidence: TemplateConfidence = 'unknown';
  if (pct >= 70 && best.meetsRequired) confidence = 'high';
  else if (pct >= 45 && best.meetsRequired) confidence = 'medium';
  else if (pct >= 25) confidence = 'low';

  const warnings: string[] = [];
  if (!best.meetsRequired) {
    warnings.push(`Thiếu cột đặc trưng của ${IMPORT_TAB_META[best.sig.id].label}.`);
  }
  if (second && second.score > 0 && best.score - second.score < 15) {
    warnings.push(
      `Gần giống ${IMPORT_TAB_META[second.sig.id].label} (${Math.round((second.score / second.maxScore) * 100)}%). Vui lòng xác nhận lại.`,
    );
  }
  if (confidence === 'unknown') {
    warnings.push('Không xác định được loại file. Vui lòng chọn tab thủ công.');
  }

  const template: ImportTemplate = confidence === 'unknown' ? 'unknown' : best.sig.id;

  return {
    template,
    tabId: template === 'unknown' ? null : template,
    confidence,
    score: pct,
    matchedSignals: best.matchedSignals,
    missingSignals: best.missingSignals,
    warnings,
  };
}

export function detectTemplate(headers: string[]): ImportTemplate {
  return validateImportTemplate(headers).template;
}

/**
 * Normalize a column header for matching:
 *   - Strip leading numbering like "3. " or "16a. "
 *   - Lowercase
 *   - Collapse whitespace
 */
export function normalizeHeader(h: string): string {
  return h
    .trim()
    .replace(/^["']+|["']+$/g, '') // Strip surrounding quotes from AppSheet CSV exports
    .replace(/^\d+[a-z]*\.?\s*/i, '') // Remove "3. " / "16a. " / "1.1."
    .replace(/^[ivxlc]+\.\s*/i, '') // Remove Roman-numeral section prefixes ("I. ", "III. ")
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

/** Find a raw cell value by matching normalized header text. */
function getRawCol(raw: Record<string, string>, ...headerIncludes: string[]): string {
  for (const inc of headerIncludes) {
    const target = normalizeHeader(inc);
    for (const [key, val] of Object.entries(raw)) {
      const nh = normalizeHeader(key);
      if (nh === target || nh.includes(target) || target.includes(nh)) {
        const v = (val ?? '').trim();
        if (v) return v;
      }
    }
  }
  return '';
}

/** Strip thousand-separators from numeric strings (e.g. "26,003,178" → "26003178"). */
function cleanNumericString(text: string): string {
  return text.replace(/,/g, '').trim();
}

