/** Parse an Excel or CSV/TSV file and return rows as Record<header, value>. */
export async function parseFile(file: File): Promise<{ headers: string[]; rows: Record<string, string>[] }> {
  const buffer = await file.arrayBuffer();

  let workbook: XLSX.WorkBook;
  const ext = file.name.split('.').pop()?.toLowerCase() ?? '';

  if (ext === 'csv' || ext === 'tsv' || ext === 'icsv' || ext === 'txt') {
    // Decode as UTF-8 text first
    const text = new TextDecoder('utf-8').decode(buffer);
    // Detect delimiter: tab if most rows have more tabs than commas
    const firstLine = text.split('\n')[0] ?? '';
    const delimiter = firstLine.split('\t').length > firstLine.split(',').length ? '\t' : ',';
    workbook = XLSX.read(text, { type: 'string', FS: delimiter });
  } else {
    workbook = XLSX.read(buffer, { type: 'array' });
  }

  const sheet = workbook.Sheets[workbook.SheetNames[0]];
  const raw: unknown[][] = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' }) as unknown[][];

  if (raw.length < 2) return { headers: [], rows: [] };

  // First non-empty row = headers
  let headerRowIdx = 0;
  for (let i = 0; i < Math.min(5, raw.length); i++) {
    const row = raw[i] as string[];
    if (row.some((c) => c && String(c).trim().length > 0)) {
      headerRowIdx = i;
      break;
    }
  }

  const headers = (raw[headerRowIdx] as string[]).map((h) => String(h ?? '').trim());

  const rows: Record<string, string>[] = [];
  for (let i = headerRowIdx + 1; i < raw.length; i++) {
    const cells = raw[i] as string[];
    // Skip completely empty rows
    if (cells.every((c) => !c || String(c).trim() === '')) continue;
    const obj: Record<string, string> = {};
    headers.forEach((h, idx) => {
      obj[h] = String(cells[idx] ?? '').trim();
    });
    rows.push(obj);
  }

  return { headers, rows };
}

// ─── Fuzzy department matching ────────────────────────────────────────────────

export interface DeptMatchResult {
  /** Resolved department option (confident single match). */
  matched?: SelectOption;
  /** Multiple candidates — user must choose. */
  candidates?: SelectOption[];
}

export function fuzzyMatchDept(text: string, options: SelectOption[]): DeptMatchResult {
  if (!text || !text.trim()) return {};
  const t = normalize(text);

  // Exact match (label)
  const exact = options.find((o) => normalize(o.label) === t);
  if (exact) return { matched: exact };

  // Contains match: option label contains query OR query contains option label
  const contains = options.filter((o) => {
    const ol = normalize(o.label);
    return ol.includes(t) || t.includes(ol);
  });

  if (contains.length === 1) return { matched: contains[0] };
  if (contains.length > 1) return { candidates: contains };

  // Word-overlap fallback
  const queryWords = t.split(/\s+/).filter((w) => w.length > 2);
  const scored = options
    .map((o) => {
      const ol = normalize(o.label);
      const score = queryWords.filter((w) => ol.includes(w)).length;
      return { o, score };
    })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score);

  if (scored.length === 1) return { matched: scored[0].o };
  if (scored.length > 1) {
    const topScore = scored[0].score;
    const top = scored.filter((x) => x.score === topScore).map((x) => x.o);
    if (top.length === 1) return { matched: top[0] };
    return { candidates: top };
  }

  return {};
}

function normalize(s: string): string {
  return s
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/[^a-z0-9\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// ─── Value parsers ────────────────────────────────────────────────────────────

function parseNotifyStatus(text: string): NotificationStatus | null {
  const t = text.toLowerCase().trim();
  if (t === 'có' || t === 'yes' || t === 'true') return NotificationStatus.Yes;
  if (t === 'không' || t === 'no' || t === 'false') return NotificationStatus.No;
  if (t.includes('không ghi') || t.includes('not recorded')) return NotificationStatus.NotRecorded;
  return null;
}

function parseOccurrenceStatus(text: string): IncidentOccurrenceStatus | null {
  const t = normalize(text);
  if (t.includes('da xay ra') || t.includes('occurred') || t === 'da xay') return IncidentOccurrenceStatus.Occurred;
  if (t.includes('chua xay ra') || t.includes('not occurred')) return IncidentOccurrenceStatus.NotOccurred;
  return null;
}

function parseSeverity(text: string): IncidentSeverity | null {
  const t = normalize(text);
  if (t.includes('nang') || t.includes('severe') || t.includes('nghiem trong')) return IncidentSeverity.Severe;
  if (t.includes('trung binh') || t.includes('medium') || t.includes('vua')) return IncidentSeverity.Medium;
  if (t.includes('nhe') || t.includes('mild')) return IncidentSeverity.Mild;
  return null;
}

function parseReportType(text: string): IncidentReportType {
  const t = normalize(text);
  if (t.includes('bat buoc') || t.includes('mandatory')) return IncidentReportType.Mandatory;
  return IncidentReportType.Voluntary;
}

function parseGender(text: string, genderOptions: SelectOption[]): string {
  const t = text.toLowerCase().trim();
  // Try option labels first
  const exact = genderOptions.find((o) => o.label.toLowerCase() === t);
  if (exact) return String(exact.value);
  // Fallback keywords
  if (t === 'nam' || t === 'male' || t === 'm') return 'male';
  if (t === 'nữ' || t === 'nu' || t === 'female' || t === 'f') return 'female';
  return t;
}

function parseSubjects(text: string): Partial<Pick<MedicalIncident, 'subjectPatient' | 'subjectStaff' | 'subjectVisitor' | 'subjectEquipment'>> {
  const t = normalize(text);
  return {
    subjectPatient:   t.includes('nguoi benh') || t.includes('benh nhan') || t.includes('patient'),
    subjectStaff:     t.includes('nhan vien') || t.includes('staff') || t.includes('y ta') || t.includes('bac si'),
    subjectVisitor:   t.includes('nguoi nha') || t.includes('khach') || t.includes('visitor'),
    subjectEquipment: t.includes('thiet bi') || t.includes('trang thiet bi') || t.includes('co so ha tang') || t.includes('equipment'),
  };
}

function parseReporterRole(text: string): Partial<Pick<MedicalIncident, 'reporterIsNurse' | 'reporterIsDoctor' | 'reporterIsPatient' | 'reporterIsVisitor' | 'reporterIsOther'>> {
  const t = normalize(text);
  const isNurse = t.includes('dieu duong') || t.includes('nurse') || t.includes('ho sinh')
    || t.includes('dd/') || t.includes('/dd') || t === 'dd'
    || t.includes('ys/') || t.includes('/ys') || t === 'ys'
    || t.includes('hs/') || t.includes('/hs') || t === 'hs';
  const isDoctor = t.includes('bac si') || t.includes('doctor') || t.includes('physician');
  const isOther = t.includes('ktv') || t.includes('ky thuat') || t.includes('hanh chinh');
  return {
    reporterIsNurse:   isNurse,
    reporterIsDoctor:  isDoctor,
    reporterIsPatient: t.includes('nguoi benh') || t.includes('benh nhan') || t.includes('patient'),
    reporterIsVisitor: t.includes('nguoi nha') || t.includes('khach') || t.includes('visitor'),
    reporterIsOther:   isOther || (t.includes('khac') || t.includes('other')),
  };
}

/** Combine date string (dd/MM/yyyy, MM/dd/yyyy, or Excel serial) and time string into ISO offset. */
function parseDatetime(dateStr: string, timeStr = ''): string | null {
  if (!dateStr || !dateStr.trim()) return null;

  // Excel serial date (AppSheet/XLSX exports): e.g. 46034.36667824074
  const serial = parseFloat(dateStr.replace(',', '.'));
  if (!isNaN(serial) && serial > 30000 && !dateStr.includes('/')) {
    const epochMs   = Date.UTC(1899, 11, 30);
    const dayOffset = Math.floor(serial);
    const base      = new Date(epochMs + dayOffset * 86400000);
    const year      = base.getUTCFullYear();
    const month     = base.getUTCMonth() + 1;
    const day       = base.getUTCDate();

    let hours = 0, minutes = 0, seconds = 0;
    const frac = serial - dayOffset;
    if (timeStr && timeStr.trim()) {
      const tStr = timeStr.trim();
      const clean = tStr.replace(/\s*(am|pm)/i, '');
      const tParts = clean.split(':').map(Number);
      [hours = 0, minutes = 0, seconds = 0] = tParts;
      if (/pm/i.test(tStr) && hours < 12) hours += 12;
      if (/am/i.test(tStr) && hours === 12) hours = 0;
    } else if (frac > 0.0001) {
      const totalSec = Math.round(frac * 86400);
      hours   = Math.floor(totalSec / 3600);
      minutes = Math.floor((totalSec % 3600) / 60);
      seconds = totalSec % 60;
    }

    const pad = (n: number) => String(n).padStart(2, '0');
    return `${year}-${pad(month)}-${pad(day)}T${pad(hours)}:${pad(minutes)}:${pad(seconds)}+07:00`;
  }

  // Support M/D/YYYY, DD/MM/YYYY, YYYY-MM-DD
  let year: number, month: number, day: number;
  const parts = dateStr.trim().split(/[\/\-]/);
  if (parts.length === 3) {
    const [a, b, c] = parts.map(Number);
    if (c > 1000) {
      // AppSheet exports use M/D/YYYY; fall back to D/M/Y when unambiguous
      if (a > 12) {
        day = a; month = b; year = c; // D/M/Y
      } else if (b > 12) {
        month = a; day = b; year = c; // M/D/Y
      } else {
        month = a; day = b; year = c; // M/D/Y (AppSheet default)
      }
    } else {
      // YYYY-MM-DD
      year = a; month = b; day = c;
    }
  } else {
    return null;
  }

  if (isNaN(year + month + day)) return null;

  // Parse time
  let hours = 0, minutes = 0, seconds = 0;
  if (timeStr && timeStr.trim()) {
    const tStr = timeStr.trim().replace(/\s*(am|pm)/i, '').replace(' PM', '').replace(' AM', '');
    const tParts = tStr.split(':').map(Number);
    [hours = 0, minutes = 0, seconds = 0] = tParts;
    // Handle PM
    if (/pm/i.test(timeStr) && hours < 12) hours += 12;
  }

  const d = new Date(year, month - 1, day, hours, minutes, seconds);
  if (isNaN(d.getTime())) return null;

  // Return as local ISO string with +07:00 offset (Vietnam)
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${year}-${pad(month)}-${pad(day)}T${pad(hours)}:${pad(minutes)}:${pad(seconds)}+07:00`;
}

/** Apply date part from ISO string and merge with a separate time string. */
function mergeDateWithTime(dateIso: string, timeStr: string): string | null {
  const datePart = dateIso.slice(0, 10);
  return parseDatetime(datePart, timeStr);
}

export interface DateFinalizeInput {
  reportDateStr: string;
  occurredDate: string;
  occurredTime: string;
  timestampStr: string;
  initialCreatedAt?: string;
}

export interface DateFinalizeResult {
  createdAt?: string;
  occurredAt?: string | null;
  dateUnresolved?: DateUnresolvedKind;
  dateFallbackUsed: ('createdAt' | 'occurredAt')[];
  warnings: string[];
}

/**
 * Resolve createdAt (Ngày báo cáo) and occurredAt (Ngày xảy ra) from import row.
 * - If one is missing, copy from the other.
 * - If both missing, mark dateUnresolved for user date-picker.
 */
export function finalizeImportDates(input: DateFinalizeInput): DateFinalizeResult {
  const { reportDateStr, occurredDate, occurredTime, timestampStr, initialCreatedAt } = input;
  const warnings: string[] = [];
  const dateFallbackUsed: ('createdAt' | 'occurredAt')[] = [];

  let createdAt = initialCreatedAt;
  let occurredAt: string | null | undefined;

  const parsedReport = reportDateStr ? parseDatetime(reportDateStr) : null;
  const parsedOccurred = occurredDate ? parseDatetime(occurredDate, occurredTime) : null;
  const parsedTimestamp = timestampStr ? parseDatetime(timestampStr) : null;

  if (!createdAt && parsedReport) createdAt = parsedReport;
  if (!createdAt && parsedTimestamp) createdAt = parsedTimestamp;
  if (parsedOccurred) occurredAt = parsedOccurred;

  if (occurredDate && !parsedOccurred) {
    warnings.push(`Không thể đọc ngày xảy ra: "${occurredDate}" "${occurredTime}"`);
  }
  if (reportDateStr && !parsedReport) {
    warnings.push(`Không thể đọc ngày báo cáo: "${reportDateStr}"`);
  }

  // Thiếu ngày xảy ra → dùng ngày báo cáo (giữ giờ xảy ra nếu có)
  if (!occurredAt && createdAt) {
    occurredAt = occurredTime
      ? mergeDateWithTime(createdAt, occurredTime) ?? createdAt
      : createdAt;
    dateFallbackUsed.push('occurredAt');
    warnings.push('Thiếu Ngày xảy ra — đã dùng Ngày báo cáo.');
  }

  // Thiếu ngày báo cáo → dùng ngày xảy ra
  if (!createdAt && occurredAt) {
    createdAt = occurredAt;
    dateFallbackUsed.push('createdAt');
    warnings.push('Thiếu Ngày báo cáo — đã dùng Ngày xảy ra.');
  }

  let dateUnresolved: DateUnresolvedKind | undefined;
  if (!createdAt && !occurredAt) {
    dateUnresolved = 'both';
  } else if (!createdAt) {
    dateUnresolved = 'createdAt';
  } else if (!occurredAt) {
    dateUnresolved = 'occurredAt';
  }

  return { createdAt, occurredAt: occurredAt ?? null, dateUnresolved, dateFallbackUsed, warnings };
}

function parseYearToDob(year: string): string | null {
  if (!year || !year.trim()) return null;
  const y = parseInt(cleanNumericString(year), 10);
  if (isNaN(y) || y < 1900 || y > new Date().getFullYear()) return null;
  return `${y}-01-01`;
}

/** Parse M/D/YYYY or DD/MM/YYYY to YYYY-MM-DD for date inputs. */
function parseDateOnly(dateStr: string): string | null {
  if (!dateStr?.trim()) return null;
  const dt = parseDatetime(dateStr);
  if (!dt) return null;
  return dt.slice(0, 10);
}

/** Parse "9:26:29 AM" → "09:26" for time inputs. */
function parseTimeOnly(timeStr: string): string {
  if (!timeStr?.trim()) return '';
  const dt = parseDatetime('1/1/2000', timeStr);
  if (!dt) return '';
  return dt.slice(11, 16);
}

// ─────────────────────────────────────────────────────────────────────────────
// Section II - incident type group parsing (phantich template)
// ─────────────────────────────────────────────────────────────────────────────

function parseIncidentTypeGroups(raw: Record<string, string>) {
  const groups = createEmptyIncidentTypeGroups();
  const norm = (s: string) => normalize(s);
  const isNo = (s: string) => !s || s === 'khong' || s.startsWith('khong ');

  // Group 1
  const g1 = norm(getRawCol(raw, '1. Thực hiện quy trình kỹ thuật, thủ thuật chuyên môn', 'Thực hiện quy trình kỹ thuật'));
  if (isNo(g1)) {
    groups.group1.none = true;
  } else {
    groups.group1.none = false;
    if (g1.includes('dong y')) groups.group1.noPatientConsent = true;
    if (g1.includes('sai thu thuat') || g1.includes('sai quy trinh') || g1.includes('sai phuong phap')) groups.group1.wrongProcedure = true;
    if (g1.includes('bo sot dung cu')) groups.group1.forgottenInstruments = true;
    if (g1.includes('tu vong khi sinh')) groups.group1.deathDuringBirth = true;
    if (g1.includes('khong thuc hien')) groups.group1.noIndication = true;
    if (g1.includes('sai nguoi benh')) groups.group1.wrongPatient = true;
    if (g1.includes('sai vi tri')) groups.group1.wrongSurgicalSite = true;
    if (g1.includes('tu vong trong thai ky')) groups.group1.deathDuringPregnancy = true;
    if (g1.includes('tu vong so sinh')) groups.group1.neonatalDeath = true;
  }

  // Group 2: Nhiễm khuẩn
  const g2 = norm(getRawCol(raw, '2. Nhiễm khuẩn bệnh viện', 'Nhiễm khuẩn bệnh viện'));
  if (isNo(g2)) {
    groups.group2.none = true;
  } else {
    if (g2.includes('nhiem khuan huyet') || g2.includes('nhiem trung huyet')) groups.group2.bloodstreamInfection = true;
    if (g2.includes('viem phoi')) groups.group2.pneumonia = true;
    if (g2.includes('nhiem khuan vet mo')) groups.group2.surgicalSiteInfection = true;
    if (g2.includes('nhiem khuan tiet nieu')) groups.group2.urinaryInfection = true;
    if (g2.includes('khac')) groups.group2.otherInfections = true;
  }

  // Group 3: Thuốc
  const g3 = norm(getRawCol(raw, '3. Thuốc và dịch truyền', 'Thuốc và dịch truyền'));
  if (isNo(g3)) {
    groups.group3.none = true;
  } else {
    if (g3.includes('cap phat sai')) groups.group3.wrongMedDispensed = true;
    if (g3.includes('thieu thuoc')) groups.group3.missingMedication = true;
    if (g3.includes('sai lieu')) groups.group3.wrongDose = true;
    if (g3.includes('sai thoi gian')) groups.group3.wrongTiming = true;
    if (g3.includes('sai y lenh')) groups.group3.wrongOrder = true;
    if (g3.includes('bo sot thuoc') || g3.includes('bo sot lieu')) groups.group3.missedDose = true;
    if (g3.includes('sai thuoc') && !g3.includes('sai lieu')) groups.group3.wrongMedication = true;
    if (g3.includes('sai nguoi benh')) groups.group3.wrongPatient = true;
    if (g3.includes('sai duong dung')) groups.group3.wrongRoute = true;
  }

  // Group 4: Máu
  const g4 = norm(getRawCol(raw, '4. Máu và các chế phẩm máu', 'Máu và các chế phẩm máu'));
  if (isNo(g4)) {
    groups.group4.none = true;
  } else {
    if (g4.includes('phan ung') || g4.includes('tai bien')) groups.group4.transfusionReaction = true;
    if (g4.includes('sai lieu') || g4.includes('sai thoi diem')) groups.group4.wrongDoseTiming = true;
    if (g4.includes('nham mau') || g4.includes('nham che pham')) groups.group4.wrongBloodProduct = true;
  }

  // Group 5: Thiết bị y tế
  const g5 = norm(getRawCol(raw, '5. Thiết bị y tế', 'Thiết bị y tế'));
  if (isNo(g5)) {
    groups.group5.none = true;
  } else {
    if (g5.includes('thieu thong tin') || g5.includes('huong dan su dung')) groups.group5.lackOfManual = true;
    if (g5.includes('loi thiet bi') || g5.includes('hu hong')) groups.group5.deviceError = true;
    if (g5.includes('thieu') || g5.includes('khong phu hop')) groups.group5.missingOrInappropriate = true;
  }

  // Group 6: Hành vi
  const g6 = norm(getRawCol(raw, '6. Hành vi', 'Hành vi'));
  if (isNo(g6)) {
    groups.group6.none = true;
  } else {
    if (g6.includes('tu hai') || g6.includes('tu tu')) groups.group6.selfHarmTendency = true;
    if (g6.includes('quay roi') && g6.includes('nhan vien')) groups.group6.sexualHarassByStaff = true;
    if (g6.includes('quay roi') && (g6.includes('benh nhan') || g6.includes('khach'))) groups.group6.sexualHarassByPatient = true;
    if (g6.includes('xam hai')) groups.group6.physicalAbuse = true;
    if (g6.includes('tu tu')) groups.group6.suicideAttempt = true;
    if (g6.includes('tron vien')) groups.group6.elopement = true;
  }

  // Group 7: Tai nạn
  const g7 = norm(getRawCol(raw, '7. Tai nạn đối với người bệnh', 'Tai nạn đối với người bệnh'));
  if (isNo(g7)) {
    groups.group7.none = true;
  } else {
    if (g7.includes('te nga') || g7.includes('truot nga')) groups.group7.fall = true;
    const fallConseq = norm(getRawCol(raw, '7.1. Hậu quả bị trượt ngã', 'Hậu quả bị trượt ngã'));
    if (fallConseq.includes('khong anh huong')) groups.group7.fallConsequenceNoEffect = true;
    if (fallConseq.includes('mo mem')) groups.group7.fallConsequenceSoftTissue = true;
    if (fallConseq.includes('gay xuong') || fallConseq.includes('gãy')) groups.group7.fallConsequenceFracture = true;
    if (fallConseq.includes('tu vong')) groups.group7.fallConsequenceDeath = true;
    if (fallConseq.includes('tray da')) groups.group7.fallConsequenceAbrasion = true;
    if (fallConseq.includes('ton thuong co quan')) groups.group7.fallConsequenceOrgan = true;
    if (fallConseq.includes('chan thuong so nao')) groups.group7.fallConsequenceBrainTrauma = true;
    groups.group7.fallLocation = getRawCol(raw, '7.2 Địa điểm bị trượt ngã', 'Địa điểm bị trượt ngã');
  }

  // Group 8: Hạ tầng
  const g8 = norm(getRawCol(raw, '8. Hạ tầng cơ sở', 'Hạ tầng cơ sở'));
  if (isNo(g8)) {
    groups.group8.none = true;
  } else {
    if (g8.includes('hu hong') || g8.includes('bi loi') || g8.includes('loi')) groups.group8.damaged = true;
    if (g8.includes('thieu') || g8.includes('khong phu hop')) groups.group8.missingOrInappropriate = true;
  }

  // Group 9: Quản lý nguồn lực
  const g9 = norm(getRawCol(raw, '9. Quản lý nguồn lực, tổ chức', 'Quản lý nguồn lực'));
  if (isNo(g9)) {
    groups.group9.none = true;
  } else {
    if (g9.includes('dich vu')) groups.group9.inadequateServices = true;
    if (g9.includes('nguon luc')) groups.group9.inadequateResources = true;
    if (g9.includes('chinh sach') || g9.includes('quy trinh')) groups.group9.inadequatePolicies = true;
  }

  // Group 10: Hồ sơ
  const g10 = norm(getRawCol(raw, '10. Hồ sơ, tài liệu, thủ tục hành chính', 'Hồ sơ, tài liệu'));
  if (isNo(g10)) {
    groups.group10.none = true;
  } else {
    if (g10.includes('mat') || g10.includes('thieu')) groups.group10.missingDocuments = true;
    if (g10.includes('khong ro rang') || g10.includes('khong hoan chinh')) groups.group10.unclearDocuments = true;
    if (g10.includes('cho doi')) groups.group10.longWaitTime = true;
    if (g10.includes('cham')) groups.group10.lateDocuments = true;
    if (g10.includes('nham')) groups.group10.wrongDocuments = true;
    if (g10.includes('phuc tap')) groups.group10.complexProcedures = true;
  }

  // Group 11: Khác
  const g11 = norm(getRawCol(raw, '11. Khác', 'Khác'));
  const summaryCol = getRawCol(raw, 'KẾT LUẬN PHÂN LOẠI SỰ CỐ THEO NHÓM SỰ CỐ');
  if (!isNo(g11)) {
    groups.group11.notListedAbove = true;
    groups.group11.otherReason = getRawCol(raw, '11. Khác', 'Khác');
  }
  if (summaryCol.includes('11. Khác') || summaryCol.includes('11.')) {
    // Use summary to activate the referenced group when sub-columns are empty
    const sn = norm(summaryCol);
    if (sn.includes('1.')) { groups.group1.none = false; groups.group1.wrongProcedure = groups.group1.wrongProcedure || sn.includes('quy trinh'); }
    if (sn.includes('5.')) { groups.group5.none = false; groups.group5.deviceError = true; }
    if (sn.includes('8.')) { groups.group8.none = false; groups.group8.damaged = true; }
    if (sn.includes('10.')) { groups.group10.none = false; }
    if (sn.includes('11.')) groups.group11.notListedAbove = true;
  }

  return groups;
}

