function parseCauseGroups(raw: Record<string, string>) {
  const groups = createEmptyCauseGroups();
  const norm = (s: string) => normalize(s);
  const isNo = (s: string) => !s || s === 'khong' || s.startsWith('khong ');

  const parseStaffPatientCause = (text: string, group: typeof groups.group1) => {
    if (isNo(text)) {
      group.none = true;
      return;
    }
    group.none = false;
    if (text.includes('nhan thuc') || text.includes('kien thuc')) group.knowledge = true;
    if (text.includes('thuc hanh')) group.practice = true;
    if (text.includes('tam sinh ly') || text.includes('benh ly')) group.psychology = true;
    if (text.includes('thai do') || text.includes('hanh vi') || text.includes('cam xuc')) group.attitude = true;
    if (text.includes('giao tiep')) group.communication = true;
    if (text.includes('xa hoi')) group.socialFactors = true;
  };

  parseStaffPatientCause(norm(getRawCol(raw, '1. Nhân viên', 'Nhân viên')), groups.group1);
  parseStaffPatientCause(norm(getRawCol(raw, '2. Người bệnh', 'Người bệnh')), groups.group2);

  const c3 = norm(getRawCol(raw, '3. Môi trường làm việc', 'Môi trường làm việc'));
  if (isNo(c3)) {
    groups.group3.none = true;
  } else {
    groups.group3.none = false;
    if (c3.includes('co so vat chat') || c3.includes('ha tang') || c3.includes('trang thiet bi')) groups.group3.facilities = true;
    if (c3.includes('danh gia') || c3.includes('an toan') || c3.includes('rui ro')) groups.group3.safetyAssessment = true;
    if (c3.includes('noi quy') || c3.includes('quy dinh') || c3.includes('quy trinh')) groups.group3.regulations = true;
    if (c3.includes('khoang cach')) groups.group3.distanceToWork = true;
  }

  const c4 = norm(getRawCol(raw, '4. Tổ chức/ dịch vụ', 'Tổ chức/ dịch vụ'));
  if (isNo(c4)) {
    groups.group4.none = true;
  } else {
    groups.group4.none = false;
    if (c4.includes('chinh sach') || c4.includes('quy trinh') || c4.includes('huong dan')) groups.group4.policies = true;
    if (c4.includes('van hoa')) groups.group4.culture = true;
    if (c4.includes('tuan thu')) groups.group4.standardCompliance = true;
    if (c4.includes('lam viec nhom')) groups.group4.teamwork = true;
  }

  const summary = getRawCol(raw, 'KẾT LUẬN PHÂN LOẠI SỰ CỐ THEO NHÓM NGUYÊN NHÂN');
  if (summary.includes('1. Nhân viên') && groups.group1.none) {
    groups.group1.none = false;
    groups.group1.practice = true;
  }
  if (summary.includes('3. Môi trường') && groups.group3.none) {
    groups.group3.none = false;
    groups.group3.facilities = true;
  }

  const c5 = norm(getRawCol(raw, '5. Yếu tố bên ngoài', 'Yếu tố bên ngoài'));
  if (isNo(c5)) {
    groups.group5.none = true;
  } else {
    groups.group5.none = false;
    if (
      c5.includes('san pham') ||
      c5.includes('cong nghe') ||
      c5.includes('co so ha tang') ||
      c5.includes('ha tang')
    ) {
      groups.group5.productTechnologyInfrastructure = true;
    }
  }

  const c6 = norm(getRawCol(raw, '6. Khác', 'Khác'));
  if (isNo(c6)) {
    groups.group6.none = true;
  } else {
    groups.group6.none = false;
    groups.group6.otherReason = getRawCol(raw, '6. Khác', 'Khác').trim();
  }

  if (summary.includes('5. Yếu tố bên ngoài') && groups.group5.none) {
    groups.group5.none = false;
    groups.group5.productTechnologyInfrastructure = true;
  }
  if (summary.includes('6. Khác') && groups.group6.none && !groups.group6.otherReason) {
    groups.group6.none = false;
  }

  return groups;
}

