function parseInjurySeverityPatient(text: string): string {
  const t = text.trim();
  if (/^NC\d_[A-I]$/i.test(t)) return t.toUpperCase();
  const tn = normalize(t);
  if (tn.includes('nc0') || tn.includes('chua xay ra')) return 'NC0_A';
  if (tn.includes('nc1') || tn.includes('ton thuong nhe')) {
    if (/\(nc1\)\s*c\b/i.test(t) || /\bnc1[_\s-]*c\b/i.test(t)) return 'NC1_C';
    if (/\(nc1\)\s*d\b/i.test(t) || /\bnc1[_\s-]*d\b/i.test(t)) return 'NC1_D';
    return 'NC1_B';
  }
  if (tn.includes('nc2') || tn.includes('trung binh')) {
    if (tn.includes('g')) return 'NC2_G';
    if (tn.includes('f')) return 'NC2_F';
    return 'NC2_E';
  }
  if (tn.includes('nc3') || tn.includes('nang') || tn.includes('nghiem trong')) {
    if (tn.includes('i')) return 'NC3_I';
    return 'NC3_H';
  }
  return t;
}

function parseInjuryOrg(text: string): Partial<import('../models/MedicalIncident').ManagementAnalysis> {
  const tn = normalize(text);
  return {
    injuryOrgPropertyDamage:       tn.includes('tai san') || tn.includes('thiet hai tai san'),
    injuryOrgIncreasedResources:   tn.includes('nguon luc') || tn.includes('tang nguon'),
    injuryOrgMediaAttention:       tn.includes('truyen thong') || tn.includes('bao chi'),
    injuryOrgPatientComplaint:     tn.includes('khieu nai') || tn.includes('phan nan'),
    injuryOrgReputationDamage:     tn.includes('danh tieng') || tn.includes('uy tin'),
    injuryOrgLegalIntervention:    tn.includes('phap luat') || tn.includes('phap ly') || tn.includes('kien'),
    injuryOrgOther:                tn.includes('khac') || tn === 'khong',
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Main row mapper
// ─────────────────────────────────────────────────────────────────────────────

export interface MapRowOptions {
  departmentOptions: SelectOption[];
  genderOptions: SelectOption[];
}

export function mapRow(
  rowIndex: number,
  raw: Record<string, string>,
  template: ImportTemplate,
  opts: MapRowOptions,
): ImportRow {
  const mapped: Partial<MedicalIncident> = {
    status: IncidentStatus.Draft,
  };
  const unresolved: Record<string, SelectOption[]> = {};
  const warnings: string[] = [];

  const map = template === 'phantich'
    ? PHANTICH_COLUMN_MAP
    : template === 'danhgia'
    ? DANHGIA_COLUMN_MAP
    : DANHSACH_COLUMN_MAP;

  let occurredDate = '';
  let occurredTime = '';
  let timestampStr = '';
  let reportDateStr = '';

  // managementAnalysis accumulator (danhgia template)
  const mgmt: Record<string, unknown> = {};
  let hasMgmt = false;

  // staffAnalysis accumulator
  const sa: Partial<StaffAnalysis> & { _analysedBy?: string } = {};
  let hasSa = false;

  for (const [rawHeader, rawValue] of Object.entries(raw)) {
    if (!rawValue || !rawValue.trim()) continue;

    const normH = normalizeHeader(rawHeader);
    const fieldKey = map[normH] as string | undefined;

    if (!fieldKey) continue;
    if (fieldKey === '_skip') continue;

    const v = rawValue.trim();

    // ── legacyId: store raw string (MSSC) ─────────────────────────────────
    if (fieldKey === 'legacyId') {
      mapped.legacyId = v;
      continue;
    }

    // ── _timestamp: 'Dấu thời gian' — Google Form submission time ────────
    if (fieldKey === '_timestamp') {
      timestampStr = v;
      const parsed = parseDatetime(v);
      if (parsed) mapped.createdAt = parsed;
      continue;
    }

    if (fieldKey === '_reportDate') {
      reportDateStr = v;
      const parsed = parseDatetime(v);
      if (parsed && !mapped.createdAt) mapped.createdAt = parsed;
      continue;
    }

    // ── createdAt: Google Form submission timestamp → store for reference ─
    if (fieldKey === 'createdAt') {
      const parsed = parseDatetime(v);
      if (parsed) mapped.createdAt = parsed;
      continue;
    }

    // ── Staff analysis fields ────────────────────────────────────────────
    if (fieldKey === '_sa_detailedDescription')        { sa.detailedDescription = v;         hasSa = true; continue; }
    if (fieldKey === '_sa_treatmentOrders')            { sa.treatmentOrders = v;              hasSa = true; continue; }
    if (fieldKey === '_sa_correctiveActions')          { sa.correctiveActions = v;            hasSa = true; continue; }
    if (fieldKey === '_sa_preventionRecommendations')  { sa.preventionRecommendations = v;    hasSa = true; continue; }
    if (fieldKey === '_sa_affectedSubjects')           { sa.affectedSubjects = v;             hasSa = true; continue; }
    if (fieldKey === '_sa_incidentLocation')           { sa.incidentLocation = v;             hasSa = true; continue; }
    if (fieldKey === '_sa_analysedBy')                 { sa._analysedBy = v;                  hasSa = true; continue; }
    if (fieldKey === '_sa_leaderTitle')                { sa._analysedBy = sa._analysedBy ?? v; hasSa = true; continue; }
    if (fieldKey === '_serviceMismatch') {
      mapped.isServiceMismatch = v.toLowerCase() === 'có' || v.toLowerCase() === 'co';
      continue;
    }

    // ── Management analysis fields (danhgia template) ────────────────────
    if (fieldKey === '_mgmt_analysisDate')   { mgmt['analysisDate'] = v; hasMgmt = true; continue; }
    if (fieldKey === '_mgmt_analysisTime')   { mgmt['analysisTime'] = v; hasMgmt = true; continue; }
    if (fieldKey === '_mgmt_leaderTitle')    { mgmt['leaderTitle']  = v; hasMgmt = true; continue; }
    if (fieldKey === '_mgmt_analysedBy')     { mgmt['analysedBy']   = v; hasMgmt = true; continue; }
    if (fieldKey === '_mgmt_findingsSummary') { mgmt['findingsSummary'] = v; hasMgmt = true; continue; }
    if (fieldKey === '_mgmt_discussedWithReporter') {
      mgmt['discussedWithReporter'] = parseNotifyStatus(v); hasMgmt = true; continue;
    }
    if (fieldKey === '_mgmt_specificRecommendations') { mgmt['specificRecommendations'] = v; hasMgmt = true; continue; }
    if (fieldKey === '_mgmt_matchesOfficialRecommendations') {
      mgmt['matchesOfficialRecommendations'] = parseNotifyStatus(v); hasMgmt = true; continue;
    }
    if (fieldKey === '_mgmt_officialRecommendationDetail') {
      mgmt['recommendations'] = v; hasMgmt = true; continue;
    }
    if (fieldKey === '_mgmt_injurySeverityPatient') {
      mgmt['injurySeverityPatient'] = parseInjurySeverityPatient(v); hasMgmt = true; continue;
    }
    if (fieldKey === '_mgmt_injuryOrg') {
      Object.assign(mgmt, parseInjuryOrg(v)); hasMgmt = true; continue;
    }
    if (fieldKey === '_mgmt_rootCauseAnalysis') { mgmt['rootCauseAnalysis'] = v; hasMgmt = true; continue; }
    if (fieldKey === '_mgmt_correctiveActions') { mgmt['correctiveActions'] = v; hasMgmt = true; continue; }
    if (fieldKey === '_mgmt_expertEmail')        { mgmt['expertEmail']       = v; hasMgmt = true; continue; }

    // ── Date/time accumulator ────────────────────────────────────────────
    if (fieldKey === '_occurredDate') { occurredDate = v; continue; }
    if (fieldKey === '_occurredTime') { occurredTime = v; continue; }

    // ── Subjects ─────────────────────────────────────────────────────────
    if (fieldKey === '_subjects') {
      Object.assign(mapped, parseSubjects(v));
      continue;
    }

    // ── Reporter role ─────────────────────────────────────────────────────
    if (fieldKey === '_reporterRole') {
      Object.assign(mapped, parseReporterRole(v));
      if (v && !Object.values(parseReporterRole(v)).some(Boolean)) {
        mapped.reporterIsOther = true;
        mapped.reporterOtherDetail = v;
      }
      continue;
    }

    // ── Department fields (fuzzy match) ──────────────────────────────────
    if (fieldKey === 'departmentId' || fieldKey === 'reportingDepartmentId') {
      const result = fuzzyMatchDept(v, opts.departmentOptions);
      if (result.matched) {
        (mapped as Record<string, unknown>)[fieldKey] = result.matched.value;
        const nameField = fieldKey === 'departmentId' ? 'departmentName' : 'reportingDepartmentName';
        (mapped as Record<string, unknown>)[nameField] = result.matched.label;
      } else if (result.candidates && result.candidates.length > 0) {
        unresolved[fieldKey] = result.candidates;
        // Set raw text as a hint
        (mapped as Record<string, unknown>)[fieldKey] = '';
      } else {
        warnings.push(`Không tìm thấy khoa phù hợp với: "${v}" (cột: ${rawHeader})`);
        unresolved[fieldKey] = opts.departmentOptions;
      }
      continue;
    }

    // ── Enum / parsed fields ─────────────────────────────────────────────
    if (fieldKey === 'reportType')          { mapped.reportType          = parseReportType(v);         continue; }
    if (fieldKey === 'occurrenceStatus')    { mapped.occurrenceStatus    = parseOccurrenceStatus(v);   continue; }
    if (fieldKey === 'severity')            { mapped.severity            = parseSeverity(v);            continue; }
    if (fieldKey === 'notifyDoctor')        { mapped.notifyDoctor        = parseNotifyStatus(v);        continue; }
    if (fieldKey === 'recordInMedicalRecord') { mapped.recordInMedicalRecord = parseNotifyStatus(v);   continue; }
    if (fieldKey === 'notifyPatient')       { mapped.notifyPatient       = parseNotifyStatus(v);        continue; }
    if (fieldKey === 'notifyFamily')        { mapped.notifyFamily        = parseNotifyStatus(v);        continue; }
    if (fieldKey === 'patientDob')          { mapped.patientDob          = parseYearToDob(v);           continue; }
    if (fieldKey === 'patientGender')       { mapped.patientGender       = parseGender(v, opts.genderOptions); continue; }
    if (fieldKey === 'patientCode')         { mapped.patientCode         = cleanNumericString(v);       continue; }

    // ── Simple string fields ─────────────────────────────────────────────
    (mapped as Record<string, unknown>)[fieldKey] = v;
  }

  // Finalize createdAt & occurredAt with bidirectional fallback
  const dateResult = finalizeImportDates({
    reportDateStr,
    occurredDate,
    occurredTime,
    timestampStr,
    initialCreatedAt: mapped.createdAt,
  });
  if (dateResult.createdAt) mapped.createdAt = dateResult.createdAt;
  if (dateResult.occurredAt) mapped.occurredAt = dateResult.occurredAt;
  warnings.push(...dateResult.warnings);

  // Finalize managementAnalysis for danhgia template
  if (hasMgmt && template === 'danhgia') {
    const rawAnalysisDate = String(mgmt['analysisDate'] ?? '');
    const rawAnalysisTime = String(mgmt['analysisTime'] ?? '');
    mapped.managementAnalysis = {
      findingsSummary:               String(mgmt['findingsSummary'] ?? ''),
      discussedWithReporter:         mgmt['discussedWithReporter'] as NotificationStatus | undefined,
      matchesOfficialRecommendations: mgmt['matchesOfficialRecommendations'] as NotificationStatus | undefined,
      specificRecommendations:       String(mgmt['specificRecommendations'] ?? ''),
      injurySeverityPatient:         String(mgmt['injurySeverityPatient'] ?? ''),
      injuryOrgPropertyDamage:       Boolean(mgmt['injuryOrgPropertyDamage']),
      injuryOrgIncreasedResources:   Boolean(mgmt['injuryOrgIncreasedResources']),
      injuryOrgMediaAttention:       Boolean(mgmt['injuryOrgMediaAttention']),
      injuryOrgPatientComplaint:     Boolean(mgmt['injuryOrgPatientComplaint']),
      injuryOrgReputationDamage:     Boolean(mgmt['injuryOrgReputationDamage']),
      injuryOrgLegalIntervention:    Boolean(mgmt['injuryOrgLegalIntervention']),
      injuryOrgOther:                Boolean(mgmt['injuryOrgOther']),
      rootCauseAnalysis:             String(mgmt['rootCauseAnalysis'] ?? ''),
      correctiveActions:             String(mgmt['correctiveActions'] ?? ''),
      preventiveActions:             '',
      recommendations:               String(mgmt['recommendations'] ?? ''),
      expertEmail:                   String(mgmt['expertEmail'] ?? ''),
      analysedById:                  '',
      analysedByCode:                '',
      analysedBy:                    String(mgmt['analysedBy'] ?? ''),
      leaderTitle:                   String(mgmt['leaderTitle'] ?? ''),
      analysisDate:                  parseDateOnly(rawAnalysisDate),
      analysisTime:                  parseTimeOnly(rawAnalysisTime),
    };
  }

  // Finalize staffAnalysis for phantich template
  if (template === 'phantich') {
    const detailedDesc = sa.detailedDescription
      ?? getRawCol(raw, 'I. MÔ TẢ CHỈ TIẾT SỰ CỐ', 'I. MÔ TẢ CHI TIẾT SỰ CỐ');
    const hasContent = Boolean(
      detailedDesc || sa.treatmentOrders || sa.correctiveActions
      || sa.preventionRecommendations || sa.affectedSubjects || sa.incidentLocation,
    );
    if (hasContent || hasSa) {
      const incidentTypes = parseIncidentTypeGroups(raw);
      const causeGroups   = parseCauseGroups(raw);
      mapped.staffAnalysis = {
        detailedDescription:       detailedDesc,
        affectedSubjects:          sa.affectedSubjects ?? getRawCol(raw, 'Đối tượng chịu ảnh hưởng'),
        incidentLocation:          sa.incidentLocation ?? getRawCol(raw, 'Địa điểm xảy ra sự cố'),
        incidentTypeGroups:        incidentTypes,
        treatmentOrders:           sa.treatmentOrders ?? getRawCol(raw, 'III. ĐIỀU TRỊ/Y LỆNH ĐÃ ĐƯỢC THỰC HIỆN'),
        causeGroups:               causeGroups,
        correctiveActions:         sa.correctiveActions ?? getRawCol(raw, 'VI. HÀNH ĐỘNG KHẮC PHỤC SỰ CỐ'),
        preventionRecommendations: sa.preventionRecommendations ?? getRawCol(raw, 'VII. ĐỀ XUẤT KHUYẾN CÁO PHÒNG NGỪA SỰ CỐ'),
      };
      if (detailedDesc) {
        mapped.status = IncidentStatus.InAnalysis;
      }
    }
  }

  return {
    rowIndex,
    raw,
    mapped,
    unresolved,
    warnings,
    dateUnresolved: dateResult.dateUnresolved,
    dateFallbackUsed: dateResult.dateFallbackUsed.length ? dateResult.dateFallbackUsed : undefined,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Batch mapper
// ─────────────────────────────────────────────────────────────────────────────

export function mapAllRows(
  rawRows: Record<string, string>[],
  template: ImportTemplate,
  opts: MapRowOptions,
): ImportRow[] {
  return rawRows.map((raw, idx) => mapRow(idx, raw, template, opts));
}

/**
 * Build a Map from legacyId (MSSC) → ImportRow for fast lookup.
 * Rows without a legacyId are ignored.
 */
export function buildMsscMap(rows: ImportRow[]): Map<string, ImportRow> {
  const map = new Map<string, ImportRow>();
  for (const row of rows) {
    const rec = row.mapped as Record<string, unknown>;
    const mssc = (rec.legacyId ?? rec.idCode) as string | undefined;
    if (mssc) map.set(String(mssc), row);
  }
  return map;
}

/**
 * Merge phantich and danhgia analysis data into primary danhsach rows by MSSC.
 * Enriches missing incident fields from analysis files when available.
 */
export function mergeImportRows(
  danhsachRows: ImportRow[],
  phantichRows: ImportRow[],
  danhgiaRows:  ImportRow[],
): ImportRow[] {
  if (phantichRows.length === 0 && danhgiaRows.length === 0) return danhsachRows;

  const phantichMap = buildMsscMap(phantichRows);
  const danhgiaMap  = buildMsscMap(danhgiaRows);

  const enrichFields: (keyof MedicalIncident)[] = [
    'patientName', 'patientCode', 'patientDob', 'patientGender',
    'departmentId', 'departmentName', 'incidentDepartmentLocation',
  ];

  return danhsachRows.map((row) => {
    const mssc = (row.mapped as Record<string, unknown>).legacyId as string | undefined;
    if (!mssc) return row;

    const phantich = phantichMap.get(mssc);
    const danhgia  = danhgiaMap.get(mssc);
    if (!phantich && !danhgia) return row;

    const merged = { ...row.mapped };
    if (phantich) {
      for (const key of enrichFields) {
        const existing = merged[key];
        const incoming = phantich.mapped[key];
        if ((existing == null || existing === '') && incoming != null && incoming !== '') {
          (merged as Record<string, unknown>)[key] = incoming;
        }
      }
      if (phantich.mapped.staffAnalysis && !merged.staffAnalysis) {
        merged.staffAnalysis = phantich.mapped.staffAnalysis;
      }
      if (phantich.mapped.isServiceMismatch) {
        merged.isServiceMismatch = true;
      }
    }
    if (danhgia?.mapped.managementAnalysis && !merged.managementAnalysis) {
      merged.managementAnalysis = danhgia.mapped.managementAnalysis;
    }
    return { ...row, mapped: merged };
  });
}

/** Count rows that have at least one unresolved department field. */
export function countUnresolved(rows: ImportRow[]): number {
  return rows.filter((r) => Object.keys(r.unresolved).length > 0).length;
}

/** Count rows missing report/occurrence dates (user must pick). */
export function countDateUnresolved(rows: ImportRow[]): number {
  return rows.filter((r) => r.dateUnresolved).length;
}

/** Row is ready to import when departments and dates are resolved. */
export function isImportRowReady(row: ImportRow): boolean {
  return Object.keys(row.unresolved).length === 0 && !row.dateUnresolved;
}

/** Count rows blocked by unresolved departments or dates. */
export function countImportBlockers(rows: ImportRow[]): number {
  return rows.filter((r) => !isImportRowReady(r)).length;
}

