import React from 'react';
import { MedicalIncident, IncidentStatus, IncidentSeverity } from '../../../models/MedicalIncident';
import styles from './MedicalIncidentTable.module.css';
import { Button, SelectOption } from '@linm-soft-org/linm-web-common-components';

interface Props {
  items: MedicalIncident[];
  loading?: boolean;
  statusOptions:   SelectOption[];
  severityOptions: SelectOption[];
  selectedIds?: string[];
  totalFilteredCount?: number;
  selectAllLoading?: boolean;
  enableSelection?: boolean;
  canDelete?: boolean;
  canPrint?: boolean;
  onSelectionChange?: (ids: string[]) => void;
  onSelectAllFiltered?: () => void;
  onView:   (item: MedicalIncident) => void;
  onEdit:   (item: MedicalIncident) => void;
  onDelete: (item: MedicalIncident) => void;
  onDownloadPdf: (item: MedicalIncident) => void;
}

// CSS class lookup by status/severity value (visual styling only)
const statusClass: Record<string, string> = {
  [IncidentStatus.Draft]:      styles.statusDraft,
  [IncidentStatus.Submitted]:  styles.statusSubmitted,
  [IncidentStatus.InAnalysis]: styles.statusAnalysis,
  [IncidentStatus.Resolved]:   styles.statusResolved,
  [IncidentStatus.Closed]:     styles.statusClosed,
};

const severityClass: Record<string, string> = {
  [IncidentSeverity.Severe]: styles.severitySevere,
  [IncidentSeverity.Medium]: styles.severityMedium,
  [IncidentSeverity.Mild]:   styles.severityMild,
};

const fmt = (iso: string | null | undefined) => {
  if (!iso) return '—';
  return new Date(iso).toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
};

export const MedicalIncidentTable: React.FC<Props> = ({
  items, loading, statusOptions, severityOptions,
  selectedIds = [], totalFilteredCount = 0, selectAllLoading,
  enableSelection = false, canDelete = false, canPrint = true,
  onSelectionChange, onSelectAllFiltered,
  onView, onEdit, onDelete, onDownloadPdf,
}) => {
  const allFilteredSelected =
    totalFilteredCount > 0 &&
    selectedIds.length === totalFilteredCount;
  const someSelected = selectedIds.length > 0;

  const toggleAll = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!onSelectionChange || !onSelectAllFiltered) return;
    if (allFilteredSelected) {
      onSelectionChange([]);
    } else {
      onSelectAllFiltered();
    }
  };

  const toggleRow = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!onSelectionChange) return;
    if (selectedIds.includes(id)) {
      onSelectionChange(selectedIds.filter((x) => x !== id));
    } else {
      onSelectionChange([...selectedIds, id]);
    }
  };

  if (loading) {
    return (
      <div className={styles.loadingRows}>
        {Array.from({ length: 5 }).map((_, i) => (
          <div key={i} className={styles.skeletonRow} />
        ))}
      </div>
    );
  }

  if (!items.length) {
    return (
      <div className={styles.empty}>
        <i className="fas fa-inbox" />
        <p>Chưa có sự cố y khoa nào</p>
      </div>
    );
  }

  return (
    <div className={styles.tableWrapper}>
      <table className={styles.table}>
        <thead>
          <tr>
            {enableSelection && onSelectionChange && (
              <th className={styles.checkboxCol}>
                {selectAllLoading ? (
                  <i className={`fas fa-spinner fa-spin ${styles.selectAllSpinner}`} />
                ) : (
                  <input
                    type="checkbox"
                    checked={allFilteredSelected}
                    ref={(el) => {
                      if (el) {
                        el.indeterminate = someSelected && !allFilteredSelected;
                      }
                    }}
                    onClick={toggleAll}
                    onChange={() => {}}
                    title={`Chọn tất cả ${totalFilteredCount} kết quả tìm kiếm`}
                  />
                )}
              </th>
            )}
            <th>Mã sự cố</th>
            <th>Tên sự cố</th>
            <th>Mô tả sự cố</th>
            <th>Bệnh nhân</th>
            <th>Khoa báo cáo</th>
            <th>Mức độ</th>
            <th>Trạng thái</th>
            <th>Thời gian xảy ra</th>
            <th>Người tạo</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {items.map((item) => {
            const isSelected = selectedIds.includes(item.id);
            return (
              <tr
                key={item.id}
                onClick={() => onView(item)}
                className={`${styles.row} ${isSelected ? styles.rowSelected : ''}`}
              >
                {enableSelection && onSelectionChange && (
                  <td className={styles.checkCell} onClick={(e) => toggleRow(e, item.id)}>
                    <input
                      type="checkbox"
                      checked={isSelected}
                      onChange={() => {}}
                    />
                  </td>
                )}
                <td>
                  <span className={styles.code}>{item.idCode}</span>
                </td>
                <td>
                  <span className={styles.name}>{item.incidentName}</span>
                </td>
                <td>
                  <span className={styles.description}>
                    {item.briefDescription || '—'}
                  </span>
                </td>
                <td>
                  <div className={styles.patient}>
                    <span>{item.patientName}</span>
                    {item.patientCode && (
                      <span className={styles.patientCode}>{item.patientCode}</span>
                    )}
                  </div>
                </td>
                <td>{item.reportingDepartmentName}</td>
                <td>
                  <span className={`${styles.badge} ${item.severity ? (severityClass[item.severity] ?? '') : ''}`}>
                    {severityOptions.find((o) => o.value === item.severity)?.label ?? item.severity}
                  </span>
                </td>
                <td>
                  {item.isNotMedicalIncident ? (
                    <span className={`${styles.badge} ${styles.statusNotMedical}`}>
                      <i className="fas fa-ban" style={{ marginRight: 4 }} />
                      Nhầm Sự Cố
                    </span>
                  ) : item.isServiceMismatch ? (
                    <span className={`${styles.badge} ${styles.statusMismatch}`}>
                      <i className="fas fa-exchange-alt" style={{ marginRight: 4 }} />
                      Nhầm Dịch Vụ
                    </span>
                  ) : (
                    <span className={`${styles.badge} ${statusClass[item.status] ?? ''}`}>
                      {statusOptions.find((o) => o.value === item.status)?.label ?? item.status}
                    </span>
                  )}
                </td>
                <td>{fmt(item.occurredAt)}</td>
                <td>{item.createdByName}</td>
                <td onClick={(e) => e.stopPropagation()}>
                  <div className={styles.actions}>
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={() => onEdit(item)}
                    >
                      <i className="fas fa-edit" />
                    </Button>
                    {canPrint && item.status && item.status !== IncidentStatus.Draft &&
                      <span title="Tải PDF">
                        <Button
                          variant="secondary"
                          size="sm"
                          onClick={() => onDownloadPdf(item)}
                        >
                          <i className="fas fa-file-pdf" />
                        </Button>
                      </span>
                    }
                    {canDelete && (
                    <Button
                      variant="danger"
                      size="sm"
                      onClick={() => onDelete(item)}
                    >
                      <i className="fas fa-trash" />
                    </Button>
                    )}
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
};
