import React, { useState } from 'react';
import { IncidentStatus } from '../../../models/MedicalIncident';
import styles from './BatchStatusBar.module.css';
import { Button, Select, SelectOption } from '@linm-soft-org/linm-web-common-components';

interface Props {
  selectedCount: number;
  totalFilteredCount?: number;
  statusOptions: SelectOption[];
  saving?: boolean;
  onConfirm: (status: IncidentStatus) => void;
  onClear: () => void;
}

export const BatchStatusBar: React.FC<Props> = ({
  selectedCount,
  totalFilteredCount = 0,
  statusOptions,
  saving,
  onConfirm,
  onClear,
}) => {
  const [targetStatus, setTargetStatus] = useState<IncidentStatus | ''>('');
  const [confirming, setConfirming] = useState(false);

  const handleUpdate = () => {
    if (!targetStatus) return;
    setConfirming(true);
  };

  const handleConfirm = () => {
    if (!targetStatus) return;
    setConfirming(false);
    onConfirm(targetStatus as IncidentStatus);
    setTargetStatus('');
  };

  const handleCancel = () => {
    setConfirming(false);
  };

  const selectedLabel = statusOptions.find((o) => o.value === targetStatus)?.label ?? '';
  const isAllFiltered = totalFilteredCount > 0 && selectedCount === totalFilteredCount;

  return (
    <div className={styles.bar}>
      <div className={styles.left}>
        <i className="fas fa-check-square" />
        <span>
          Đã chọn <strong>{selectedCount}</strong> sự cố
          {isAllFiltered && ' (tất cả kết quả tìm kiếm)'}
        </span>
      </div>

      {confirming ? (
        <div className={styles.confirmRow}>
          <span className={styles.confirmText}>
            Cập nhật {selectedCount} sự cố → <strong>{selectedLabel}</strong>?
          </span>
          <Button variant="primary" size="sm" onClick={handleConfirm} disabled={saving}>
            {saving ? <i className="fas fa-spinner fa-spin" /> : <i className="fas fa-check" />}
            {' '}Xác nhận
          </Button>
          <Button variant="secondary" size="sm" onClick={handleCancel} disabled={saving}>
            Hủy
          </Button>
        </div>
      ) : (
        <div className={styles.right}>
          <Select
            value={targetStatus}
            onChange={(e) => setTargetStatus(e.target.value as IncidentStatus | '')}
            size="small"
            className={styles.statusSelect}
            options={statusOptions}
            placeholder="-- Chọn trạng thái --"
          />
          <Button
            variant="primary"
            size="sm"
            onClick={handleUpdate}
            disabled={!targetStatus || saving}
          >
            <i className="fas fa-sync-alt" /> Cập nhật
          </Button>
          <Button variant="secondary" size="sm" onClick={onClear}>
            <i className="fas fa-times" /> Bỏ chọn
          </Button>
        </div>
      )}
    </div>
  );
};
