// ─── Step 1: File upload ──────────────────────────────────────────────────────

// ─── Step 1: Multi-file upload slots ─────────────────────────────────────────────────────────────

interface FileSlotCardProps {
  slotKey: SlotKey;
  slot: FileSlot | undefined;
  optionsLoading: boolean;
  onFile: (slotKey: SlotKey, slot: FileSlot) => void;
  onRemove: (slotKey: SlotKey) => void;
}

const FileSlotCard: React.FC<FileSlotCardProps> = ({ slotKey, slot, optionsLoading, onFile, onRemove }) => {
  const [dragging, setDragging] = useState(false);
  const [parsing, setParsing]   = useState(false);
  const [fileError, setFileError] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFile = useCallback(async (file: File) => {
    const allowed = ['.xlsx', '.xls', '.csv', '.tsv', '.icsv', '.txt'];
    const ext = '.' + (file.name.split('.').pop()?.toLowerCase() ?? '');
    if (!allowed.includes(ext)) { setFileError(`Định dạng không hỗ trợ: ${ext}`); return; }
    setFileError('');
    setParsing(true);
    try {
      const { headers, rows } = await parseFile(file);
      if (rows.length === 0) { setFileError('File không có dữ liệu.'); return; }
      const validation = validateImportTemplate(headers);
      const suggestedTab: SlotKey = validation.tabId ?? slotKey;
      onFile(slotKey, {
        file,
        headers,
        rawRows: rows,
        validation,
        uploadSlot: slotKey,
        assignedTab: suggestedTab,
        template: suggestedTab,
      });
      if (validation.tabId && validation.tabId !== slotKey) {
        setFileError(`ℹ️ Phát hiện: ${IMPORT_TAB_META[validation.tabId].label}. Xác nhận ở bước tiếp theo.`);
      } else if (validation.confidence === 'unknown') {
        setFileError('⚠️ Không xác định được loại file. Bạn sẽ chọn tab ở bước tiếp theo.');
      }
    } catch (e) {
      setFileError('Lỗi đọc file: ' + String(e));
    } finally {
      setParsing(false);
    }
  }, [slotKey, onFile]);

  const isLoading = optionsLoading || parsing;

  if (slot) {
    return (
      <div className={`${styles.slotCard} ${styles.slotCardDone}`}>
        <div className={styles.slotCardHeader}>
          <span className={styles.slotIcon}>
            {slotKey === 'danhsach' ? '📄' : slotKey === 'phantich' ? '🔬' : '✅'}
          </span>
          <div className={styles.slotCardInfo}>
            <div className={styles.slotCardLabel}>{SLOT_LABELS[slotKey]}</div>
            <div className={styles.slotCardFile}>
              {slot.file.name}
              <span className={styles.slotCardRows}> — {slot.rawRows.length} hàng</span>
            </div>
            {slot.validation.tabId && (
              <div className={`${styles.detectBadge} ${styles[`detectBadge_${slot.validation.confidence}`]}`}>
                Phát hiện: {IMPORT_TAB_META[slot.validation.tabId].label}
                {' '}({CONFIDENCE_LABEL[slot.validation.confidence]})
              </div>
            )}
          </div>
          <button className={styles.slotRemoveBtn} onClick={() => onRemove(slotKey)} title="Xóa file">✕</button>
        </div>
      </div>
    );
  }

  return (
    <div
      className={`${styles.slotCard} ${dragging ? styles.slotCardDragging : ''} ${isLoading ? styles.slotCardDisabled : ''}`}
      onDragOver={(e) => { if (!isLoading) { e.preventDefault(); setDragging(true); } }}
      onDragLeave={() => setDragging(false)}
      onDrop={(e) => {
        e.preventDefault(); setDragging(false);
        const file = e.dataTransfer.files[0];
        if (file && !isLoading) handleFile(file);
      }}
      onClick={() => { if (!isLoading) inputRef.current?.click(); }}
    >
      <input
        ref={inputRef}
        type="file"
        accept=".xlsx,.xls,.csv,.tsv,.icsv,.txt"
        className={styles.hiddenInput}
        onChange={(e) => { const f = e.target.files?.[0]; if (f && !isLoading) handleFile(f); e.target.value = ''; }}
      />
      <div className={styles.slotCardBody}>
        {parsing ? (
          <><span className={styles.spinner} /><span>Đang đọc file…</span></>
        ) : (
          <>
            <div className={styles.slotIcon}>
              {slotKey === 'danhsach' ? '📄' : slotKey === 'phantich' ? '🔬' : '✅'}
            </div>
            <div className={styles.slotCardLabel}>{SLOT_LABELS[slotKey]}</div>
            <div className={styles.slotCardHint}>{SLOT_HINTS[slotKey]}</div>
            <div className={styles.slotCardAction}>
              Kéo thả hoặc <span className={styles.dropLink}>chọn file</span>
            </div>
          </>
        )}
      </div>
      {fileError && <div className={styles.slotError}>{fileError}</div>}
    </div>
  );
};

