interface BulkConfirm {
  field:    string;
  rawText:  string;
  value:    string;
  label:    string;
  affectedCount: number;
}

function dateUnresolvedLabel(kind: DateUnresolvedKind): string {
  if (kind === 'both') return 'Chọn Ngày báo cáo & Ngày xảy ra';
  if (kind === 'createdAt') return 'Chọn Ngày báo cáo';
  return 'Chọn Ngày xảy ra';
}

function datePickerValue(row: ImportRow, kind: DateUnresolvedKind): string {
  if (kind === 'both') {
    return utcToLocalInputValue(row.mapped.createdAt ?? row.mapped.occurredAt ?? undefined);
  }
  if (kind === 'createdAt') return utcToLocalInputValue(row.mapped.createdAt);
  return utcToLocalInputValue(row.mapped.occurredAt ?? undefined);
}

function DateUnresolvedPicker({
  row,
  onResolveDate,
}: {
  row: ImportRow;
  onResolveDate: Step2Props['onResolveDate'];
}) {
  const kind = row.dateUnresolved;
  if (!kind) return null;

  return (
    <div className={styles.dateUnresolvedCell}>
      <span className={styles.unresolvedBadge}>⚠️ Thiếu ngày — cần chọn thủ công</span>
      <label className={styles.datePickerLabel}>
        {dateUnresolvedLabel(kind)}
        <input
          type="datetime-local"
          className={styles.datePickerInput}
          value={datePickerValue(row, kind)}
          onChange={(e) => onResolveDate(row.rowIndex, kind, e.target.value)}
        />
      </label>
    </div>
  );
}

/** Get the raw original text for a department field from a row */
const RAW_DEPT_KEYS: Record<string, string[]> = {
  departmentId:          ['8. Khoa người bệnh điều trị', 'Khoa điều trị'],
  reportingDepartmentId: ['3. Khoa/phòng báo cáo', 'Khoa/phòng báo cáo'],
};

function getRawDeptText(row: ImportRow, field: string): string {
  for (const key of RAW_DEPT_KEYS[field] ?? []) {
    if (row.raw[key]) return row.raw[key];
  }
  for (const [k, v] of Object.entries(row.raw)) {
    const kl = k.toLowerCase();
    if (field === 'departmentId' && (kl.includes('khoa người bệnh') || kl.includes('khoa điều trị'))) return v;
    if (field === 'reportingDepartmentId' && (kl.includes('báo cáo') && kl.includes('khoa'))) return v;
  }
  return '';
}

