export const ImportIncidentsModal: React.FC<Props> = ({ isOpen, onClose, onImportComplete }) => {
  const [step, setStep] = useState<Step>(1);

  // Multi-file slot state (danhsach required; phantich + danhgia optional)
  const [fileSlots, setFileSlots] = useState<Partial<Record<SlotKey, FileSlot>>>({});
  /** User-confirmed tab assignment per upload slot */
  const [tabAssignments, setTabAssignments] = useState<Partial<Record<SlotKey, SlotKey>>>({});
  /** Slots after reassignment by confirmed tab */
  const [confirmedSlots, setConfirmedSlots] = useState<Partial<Record<SlotKey, FileSlot>>>({});

  // Mapped + merged rows shown in Step 3
  const [importRows, setImportRows] = useState<ImportRow[]>([]);
  /** Step 3 showing failed rows after partial import */
  const [importErrorReview, setImportErrorReview] = useState(false);
  const [lastImportSuccessCount, setLastImportSuccessCount] = useState(0);

  // Import progress
  const [progress, setProgress] = useState<ImportProgress>({
    total: 0, done: 0, errors: [], running: false, finished: false, duplicateSkipped: 0,
  });

  // Load all form options when modal mounts
  const {
    departmentOptions,
    patientGenderOptions,
    incidentSeverityOptions,
    incidentReportTypeOptions,
    incidentOccurrenceStatusOptions,
    incidentNotifyStatusOptions,
    loading: optionsLoading,
  } = useFormOptions('import-incidents');

  // Build a combined options object for Step2 rendering
  const formOptions: FullMapRowOptions = {
    departmentOptions,
    genderOptions:           patientGenderOptions ?? [],
    reportTypeOptions:       incidentReportTypeOptions ?? [],
    occurrenceStatusOptions: incidentOccurrenceStatusOptions ?? [],
    severityOptions:         incidentSeverityOptions ?? [],
    notifyStatusOptions:     incidentNotifyStatusOptions ?? [],
  };

  // Reset on close
  useEffect(() => {
    if (!isOpen) {
      const timer = setTimeout(() => {
        setStep(1);
        setFileSlots({});
        setTabAssignments({});
        setConfirmedSlots({});
        setImportRows([]);
        setImportErrorReview(false);
        setLastImportSuccessCount(0);
        setProgress({ total: 0, done: 0, errors: [], running: false, finished: false, duplicateSkipped: 0 });
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [isOpen]);

  // Helper: build merged ImportRow[] from all slots
  const buildMergedRows = useCallback((slots: Partial<Record<SlotKey, FileSlot>>, deptOpts: typeof departmentOptions, genderOpts: typeof patientGenderOptions) => {
    const ds = slots.danhsach;
    if (!ds) return [];
    const mapOpts: MapRowOptions = { departmentOptions: deptOpts, genderOptions: genderOpts ?? [] };
    const danhsachRows = mapAllRows(ds.rawRows, 'danhsach', mapOpts);
    const phantichRows = slots.phantich ? mapAllRows(slots.phantich.rawRows, 'phantich', mapOpts) : [];
    const danhgiaRows  = slots.danhgia  ? mapAllRows(slots.danhgia.rawRows,  'danhgia',  mapOpts) : [];
    return mergeImportRows(danhsachRows, phantichRows, danhgiaRows);
  }, []);

  // Re-map rows when departmentOptions finish loading (0 → N), but only once per load.
  // Using a ref to avoid infinite loop from new array refs returned by useFormOptions every render.
  const deptLoadedRef = useRef(false);
  useEffect(() => {
    if (departmentOptions.length > 0 && !deptLoadedRef.current) {
      deptLoadedRef.current = true;
      if (fileSlots.danhsach) {
        const timer = setTimeout(() => {
          const slots = Object.keys(confirmedSlots).length > 0 ? confirmedSlots : fileSlots;
          setImportRows(buildMergedRows(slots, departmentOptions, patientGenderOptions));
        }, 0);
        return () => clearTimeout(timer);
      }
    }
    // Reset ref when options unload (modal close resets fileSlots anyway)
    if (departmentOptions.length === 0) {
      deptLoadedRef.current = false;
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [departmentOptions.length]);

  // ── Handle a new file dropped onto a slot ───────────────────────────────

  const handleSlotFile = useCallback((slotKey: SlotKey, slot: FileSlot) => {
    setFileSlots((prev) => ({ ...prev, [slotKey]: slot }));
    setTabAssignments((prev) => ({ ...prev, [slotKey]: slot.assignedTab }));
  }, []);

  const handleSlotRemove = useCallback((slotKey: SlotKey) => {
    setFileSlots((prev) => {
      const next = { ...prev };
      delete next[slotKey];
      return next;
    });
    setTabAssignments((prev) => {
      const next = { ...prev };
      delete next[slotKey];
      return next;
    });
  }, []);

  const handleAssignTab = useCallback((uploadSlot: SlotKey, assignedTab: SlotKey) => {
    setTabAssignments((prev) => ({ ...prev, [uploadSlot]: assignedTab }));
  }, []);

  // ── Step 1 → Step 2 (validate) ───────────────────────────────────────────

  const handleGoToStep2 = useCallback(() => {
    setStep(2);
  }, []);

  // ── Step 2 → Step 3 (preview) ───────────────────────────────────────────

  const handleConfirmTemplates = useCallback(() => {
    const assigned = buildAssignedSlots(fileSlots, tabAssignments);
    setConfirmedSlots(assigned);
    const merged = buildMergedRows(assigned, departmentOptions, patientGenderOptions);
    setImportRows(merged);
    setStep(3);
  }, [fileSlots, tabAssignments, departmentOptions, patientGenderOptions, buildMergedRows]);

  // ── Resolve ambiguous department ─────────────────────────────────────────

  const handleResolve = useCallback((rowIndex: number, field: string, value: string, label: string) => {
    setImportRows((prev) =>
      prev.map((r) => {
        if (r.rowIndex !== rowIndex) return r;
        const newUnresolved = { ...r.unresolved };
        if (value) delete newUnresolved[field];
        const nameField = field === 'departmentId' ? 'departmentName' : 'reportingDepartmentName';
        return { ...r, unresolved: newUnresolved, mapped: { ...r.mapped, [field]: value, [nameField]: label } };
      }),
    );
  }, []);

  const handleResolveAll = useCallback((rawText: string, field: string, value: string, label: string) => {
    const nameField = field === 'departmentId' ? 'departmentName' : 'reportingDepartmentName';
    const rawKeys = field === 'departmentId'
      ? ['8. Khoa người bệnh điều trị', 'Khoa điều trị']
      : ['3. Khoa/phòng báo cáo', 'Khoa/phòng báo cáo'];
    setImportRows((prev) =>
      prev.map((r) => {
        if (!r.unresolved[field]) return r;
        const rowRawText = rawKeys.reduce((acc: string, k: string) => acc || r.raw[k] || '', '');
        if (rowRawText !== rawText) return r;
        const newUnresolved = { ...r.unresolved };
        if (value) delete newUnresolved[field];
        return { ...r, unresolved: newUnresolved, mapped: { ...r.mapped, [field]: value, [nameField]: label } };
      }),
    );
  }, []);

  const handleResolveDate = useCallback((rowIndex: number, kind: DateUnresolvedKind, localValue: string) => {
    if (!localValue) return;
    const iso = localInputToISOWithOffset(localValue);
    setImportRows((prev) =>
      prev.map((r) => {
        if (r.rowIndex !== rowIndex) return r;
        const updates: Partial<ImportRow['mapped']> = {};
        if (kind === 'both') {
          updates.createdAt = iso;
          updates.occurredAt = iso;
        } else if (kind === 'createdAt') {
          updates.createdAt = iso;
        } else {
          updates.occurredAt = iso;
        }
        return {
          ...r,
          dateUnresolved: undefined,
          mapped: { ...r.mapped, ...updates },
        };
      }),
    );
  }, []);

  // ── Import execution ─────────────────────────────────────────────────────

  const handleImport = useCallback(async () => {
    const readyRows = importRows.filter(isImportRowReady);

    // ── Duplicate check via legacyId (MSSC) ──────────────────────────────
    const legacyIds = readyRows
      .map((r) => (r.mapped as Record<string, unknown>).legacyId as string | undefined)
      .filter((id): id is string => !!id);
    const existingSet = new Set(
      legacyIds.length > 0 ? await medicalIncidentService.checkLegacyIds(legacyIds) : [],
    );
    const rowsToImport = readyRows.filter(
      (r) => {
        const id = (r.mapped as Record<string, unknown>).legacyId as string | undefined;
        return !id || !existingSet.has(id);
      },
    );
    const duplicateSkipped = readyRows.length - rowsToImport.length;
    // ─────────────────────────────────────────────────────────────────────

    setProgress({ total: rowsToImport.length, done: 0, errors: [], running: true, finished: false, duplicateSkipped });

    const errors: string[] = [];
    const failedRows: ImportRow[] = [];
    let done = 0;

    for (const row of rowsToImport) {
      try {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        await medicalIncidentService.create({ ...row.mapped, isImported: true } as any);
        done++;
      } catch (e) {
        const message = String(e);
        errors.push(`Hàng ${row.rowIndex + 1}: ${message}`);
        failedRows.push({ ...row, importError: message });
        done++;
      }
      setProgress((p) => ({ ...p, done, errors: [...errors] }));
    }

    const successCount = rowsToImport.length - failedRows.length;
    setProgress({
      total: rowsToImport.length,
      done,
      errors,
      running: false,
      finished: true,
      duplicateSkipped,
    });

    onImportComplete({ successCount, hasErrors: failedRows.length > 0 });

    if (failedRows.length > 0) {
      setLastImportSuccessCount((prev) => prev + successCount);
      setImportRows(failedRows);
      setImportErrorReview(true);
      setStep(3);
      setProgress({ total: 0, done: 0, errors: [], running: false, finished: false, duplicateSkipped: 0 });
    }
  }, [importRows, onImportComplete]);

  const handleDismissRetry = () => {
    if (progress.running) return;
    onClose();
  };

  const handleClose = () => {
    if (progress.running) return;
    onClose();
  };

  const getTitle = () => {
    if (step === 1) return 'Nhập sự cố từ file – Bước 1: Tải file';
    if (step === 2) return 'Nhập sự cố từ file – Bước 2: Xác nhận loại file';
    if (step === 3 && importErrorReview) return 'Nhập sự cố từ file – Xem lại bản ghi lỗi';
    if (step === 3) return 'Nhập sự cố từ file – Bước 3: Xem trước dữ liệu';
    return 'Nhập sự cố từ file – Bước 4: Xác nhận';
  };

  // Primary file info for Step3 header
  const activeSlots = Object.keys(confirmedSlots).length > 0 ? confirmedSlots : fileSlots;
  const primaryFile = activeSlots.danhsach?.file ?? null;
  const primaryTemplate: ImportTemplate = activeSlots.danhsach?.template ?? 'danhsach';

  return (
    <Modal
      isOpen={isOpen}
      onClose={handleClose}
      title={getTitle()}
      size="lg"
      closeOnOverlayClick={!progress.running}
    >
      <StepIndicator current={step} />

      {step === 1 && (
        <Step1FileUpload
          optionsLoading={optionsLoading}
          slots={fileSlots}
          onFile={handleSlotFile}
          onRemove={handleSlotRemove}
          onNext={handleGoToStep2}
        />
      )}

      {step === 2 && (
        <Step2ValidateConfirm
          slots={fileSlots}
          assignments={tabAssignments}
          onAssign={handleAssignTab}
          onBack={() => setStep(1)}
          onConfirm={handleConfirmTemplates}
        />
      )}

      {step === 3 && primaryFile && (
        <Step2MapPreview
          file={primaryFile}
          template={primaryTemplate}
          rows={importRows}
          departmentOptions={departmentOptions}
          formOptions={formOptions}
          onResolve={handleResolve}
          onResolveAll={handleResolveAll}
          onResolveDate={handleResolveDate}
          onBack={() => setStep(2)}
          onNext={() => {
            setImportErrorReview(false);
            setStep(4);
          }}
          retryMode={importErrorReview}
          lastImportSuccessCount={lastImportSuccessCount}
          onDismissRetry={handleDismissRetry}
        />
      )}

      {step === 4 && (
        <Step3Confirm
          rows={importRows}
          progress={progress}
          onBack={() => setStep(3)}
          onImport={handleImport}
          onClose={handleClose}
        />
      )}
    </Modal>
  );
};

